import fs from "node:fs";
import prettier from "prettier";
import path from "node:path";
import { fileURLToPath } from "node:url";
import {
  typography,
  fontFamilies,
  fontSizePrimitives,
  lineHeightPrimitives,
  fontWeightPrimitives,
} from "../packages/tokens/src/typography.ts";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const header =
  "/* Generated by scripts/generate-typography.mjs. Do not edit. */\n";
const rem = (px) => `${px / 16}rem`;
const declarations = (entries) =>
  entries.map(([name, value]) => `    --dixy-${name}: ${value};`).join("\n");
const primitives = [
  ...Object.entries(fontFamilies).map(([name, value]) => [
    `font-${name}`,
    value,
  ]),
  ...fontSizePrimitives.map((px) => [`font-size-${px}`, rem(px)]),
  ...lineHeightPrimitives.map((px) => [`line-height-${px}`, rem(px)]),
  ...Object.entries(fontWeightPrimitives).map(([name, value]) => [
    `font-weight-${name}`,
    value,
  ]),
];
const semantic = Object.entries(typography).flatMap(([role, token]) => {
  const key = `font-${role.replaceAll(".", "-")}`;
  return [
    [`${key}-family`, `var(--dixy-font-${token.family})`],
    [`${key}-size`, `var(--dixy-font-size-${token.size})`],
    [`${key}-line-height`, `var(--dixy-line-height-${token.lineHeight})`],
    [`${key}-weight`, `var(--dixy-font-weight-${token.weight})`],
    [`${key}-letter-spacing`, `${token.letterSpacing}em`],
    [
      key,
      `var(--dixy-${key}-weight) var(--dixy-${key}-size)/var(--dixy-${key}-line-height) var(--dixy-${key}-family)`,
    ],
  ];
});
// Rebind semantic aliases at theme boundaries so family overrides resolve locally.
const css = `${header}@layer dixy.tokens {\n  :root {\n${declarations(primitives)}\n  }\n  :root, .dixy-theme {\n${declarations(semantic)}\n  }\n}\n`;
const classes = `${header}@layer dixy.components {\n${Object.keys(typography)
  .map((role) => {
    const key = role.replaceAll(".", "-");
    return `  [data-typography="${role}"] {\n    font: var(--dixy-font-${key});\n    letter-spacing: var(--dixy-font-${key}-letter-spacing);\n  }`;
  })
  .join("\n")}\n}\n`;
const outputs = {
  "packages/tokens/src/typography.css": css,
  "packages/react/src/tokens/typography-roles.css": classes,
};
if (process.argv.includes("--dist"))
  outputs["packages/tokens/dist/typography.css"] = css;
for (const [file, raw] of Object.entries(outputs)) {
  const content = await prettier.format(raw, { parser: "css" });
  const target = path.join(root, file);
  const current = fs.existsSync(target) ? fs.readFileSync(target, "utf8") : "";
  if (process.argv.includes("--check")) {
    if (current !== content)
      throw new Error(`${file} is stale. Run pnpm tokens:generate.`);
  } else if (current !== content) {
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, content);
  }
}
console.log(
  process.argv.includes("--check")
    ? "Typography CSS matches its canonical contracts."
    : "Typography CSS generated from token contracts.",
);
